  const plan2 = er.getRecoveryPlan({ category: "compile", summary: "", likelyRootCause: "", suggestedFix: "", affectedFiles: [], severity: "high" }, "step-1", 2)
  g5Assert(plan2.action === "retry_same", "G5-2a: second attempt → retry_same (not tried yet)")

