// PL-7: createPlanVersion — rewires dependencies correctly
{
  const pll = new PlanningLayer(new DAGEngine())
  const original = pll.createPlan("dep goal", [
    { id: "s1", description: "setup", dependsOn: [], verificationCriteria: [] },
