{"filePath":"/home/runner/opencode-agentic-engine/test/run-parallel.mjs","content":"// test/run-parallel.mjs — Parallel test runner
// Runs Part A sequentially, then Part B files in parallel via child processes
//
// Usage: node test/run-parallel.mjs
//
// Each _b_*.mjs file runs as a separate child Node.js process.
// Each reports results via __RESULT__:{"passed":N,"failed":M} on stdout.

import { execFile } from "child_process"
import { fileURLToPath } from "url"
import { dirname, resolve } from "path"

const __dirname = dirname(fileURLToPath(import.meta.url))

async function main() {
  console.log("=== Running Part A (sequential) ===")

  // Part A: runAll() — must complete first
  const { runAll } = await import("./_runall.mjs")
  await runAll()

  // Get progress from Part A
  const { state } = await import("./_state.mjs")
  let totalPassed = state.passed
  let totalFailed = state.failed

  console.log(`\n=== Part A complete: ${totalPassed} passed, ${totalFailed} failed ===`)
  console.log("\n=== Running Part B files in PARALLEL ===\n")

  // Part B files to run in parallel as separate node processes
  const partBFiles = [
    { file: "_b_planners.mjs", label: "Planners" },
    { file: "_b_memory.mjs", label: "Memory" },
    { file: "_b_agents.mjs", label: "Agents" },
    { file: "_b_branch.mjs", label: "Branch Coverage" },
    { file: "_b_protocols.mjs", label: "Protocols" },
  ]

  const results = await Promise.all(partBFiles.map(item => runPartB(item)))

  // Aggregate results
  for (const r of results) {
    totalPassed += r.passed
    totalFailed += r.failed
  }

  // Summary
  const G = "\x1b[32m"
  const R = "\x1b[31m"
  const RST = "\x1b[0m"
  console.log(`\n${"=".repeat(50)}`)
  console.log(`TOTAL: ${totalPassed} passed, ${totalFailed} failed in ${partBFiles.length} parallel workers`)
  if (totalFailed === 0) {
    console.log(`${G}ALL TESTS PASSED${RST}`)
    process.exit(0)
  } else {
    console.log(`${R}SOME TESTS FAILED${RST}`)
    process.exit(1)
  }
}

function runPartB({ file, label }) {
  return new Promise((resolvePromise) => {
    const childPath = resolve(__dirname, file)
    const child = execFile(process.execPath, [childPath], {
      timeout: 180000,
      maxBuffer: 10 * 1024 * 1024,
    }, (error, stdout, stderr) => {
      // Forward output to parent's stdout/stderr
      if (stdout) process.stdout.write(stdout)
      if (stderr) process.stderr.write(stderr)

      // Parse __RESULT__ line from stdout
      const resultLine = stdout.split("\n").find(l => l.startsWith("__RESULT__:"))
      if (resultLine) {
        try {
          const result = JSON.parse(resultLine.replace("__RESULT__:", ""))
          resolvePromise({ passed: result.passed || 0, failed: result.failed || 0 })
          return
        } catch {
          // fall through to error handling
        }
      }

      // No result line found
      resolvePromise({ passed: 0, failed: error ? 1 : 0 })
    })
  })
}

main().catch(e => {
  console.error("FATAL:", e.message)
  process.exit(1)
})
"}

