    console.log("ALL TESTS PASSED")
    process.exit(0)
  } else {
    console.log("SOME TESTS FAILED")
    process.exit(1)
  }
}

function runPartB(filename) {
  return new Promise((resolve) => {
    const childPath = resolve(__dirname, filename)
    const child = fork(childPath, [], {
      stdio: ["pipe", "pipe", "pipe", "ipc"],
      execArgv: []  // no special flags
    })

    let output = ""
    child.stdout.on("data", (data) => {
      const text = data.toString()
      process.stdout.write(text)  // Forward output to parent's stdout
      output += text
    })

    child.stderr.on("data", (data) => {
      process.stderr.write(data.toString())
    })

    child.on("close", (code) => {
      // Parse result from output
      const resultLine = output.split("\n").find(l => l.startsWith("__RESULT__:"))
      if (resultLine) {
        try {
          const result = JSON.parse(resultLine.replace("__RESULT__:", ""))
          resolve(result)
        } catch {
          resolve({ passed: 0, failed: 0 })
        }
      } else {
        resolve({ passed: 0, failed: code === 0 ? 0 : 1 })
      }
    })
  })
}

main().catch(e => {
  console.error("FATAL:", e.message)
  process.exit(1)
})
