{"filePath":"/home/runner/opencode-agentic-engine/test/run-parallel.mjs","content":"// test/run-parallel.mjs — Parallel test runner (in-process, zero overhead)
//
// Runs ALL tests concurrently within a single Node.js process using Promise.all().
// No child processes, no IPC overhead — just async concurrency.
//
// Usage: node test/run-parallel.mjs
//
// Architecture:
//   1. Load plugin module once (shared by all subtasks)
//   2. Part A (4 sub-files) + Part B (5 modules) → Promise.all()
//   3. state.passed/state.failed accumulated from all concurrently

import "./_common.mjs"
import { pluginDist, G, R, RST } from "./_common.mjs"
import { runCoreTests } from "./_runall-core.mjs"
import { runVerifyTests } from "./_runall-verify.mjs"
import { runAdvancedTests } from "./_runall-adv.mjs"
import { runEdgeTests } from "./_runall-edge.mjs"

async function main() {
  const runStart = Date.now()

  // Load plugin once — shared across all subtasks
  const mod = await import(pluginDist)

  // Run EVERYTHING in parallel within the same process:
  //   Part A: 4 function calls (must await import(mod) first)
  //   Part B: 5 module imports (they import _common.mjs — cached by ESM)
  await Promise.all([
    runCoreTests(mod),
    runVerifyTests(mod),
    runAdvancedTests(mod),
    runEdgeTests(mod),
    import("./_b_planners.mjs"),
    import("./_b_memory.mjs"),
    import("./_b_agents.mjs"),
    import("./_b_branch.mjs"),
    import("./_b_protocols.mjs"),
  ])

  // Results
  const { state } = await import("./_state.mjs")
  const totalMs = Date.now() - runStart
  const totalSec = (totalMs / 1000).toFixed(1)
  const status = state.failed === 0 ? "ALL TESTS PASSED" : "SOME TESTS FAILED"

  console.log(`\n${R}── Failed Tests ──${RST}`)
  for (const f of state.failedTests) {
    console.log(`  ${R}✗${RST} ${f.section ? f.section + " → " : ""}${f.msg}`)
  }

  console.log(`\nResults: ${G}${state.passed} passed${RST}, ${state.failed > 0 ? R : G}${state.failed} failed${RST} in ${totalSec}s (9 workers parallel)`)
  console.log(`${state.failed === 0 ? G : R}${status}${RST}`)
  process.exit(state.failed > 0 ? 1 : 0)
}

main().catch(e => {
  console.error("FATAL:", e.message)
  process.exit(1)
})
"}

