d=td(); mkdirSync(d,{recursive:true}); writeFileSync(join(d,'tsconfig.json'),'{}');
v=new mod.Verifier(); v.verifyAll('k',d); rmSync(d,{recursive:true,force:true});
d=td(); mkdirSync(d,{recursive:true}); writeFileSync(join(d,'tsconfig.json'),'{}');
v=new mod.Verifier(); v.detectLanguage(d); v.verifyRelated('i',d,['src/foo.ts']); rmSync(d,{recursive:true,force:true});
d=td(); mkdirSync(d,{recursive:true}); writeFileSync(join(d,'requirements.txt'),'');
v=new mod.Verifier(); v.detectLanguage(d); v.verifyRelated('pi',d,['src/module.py']); rmSync(d,{recursive:true,force:true});
