v=new mod.Verifier(); v.setLLM({call:async()=>({content:'{\"passed\":true,\"issuesFound\":[\"minor\"]}'})}); await v.verifySemantic('i','t',['test.ts'],d);
v=new mod.Verifier(); v.setLLM({call:async()=>({content:'not json'})}); await v.verifySemantic('b','t',['test.ts'],d); rmSync(d,{recursive:true,force:true});
v=new mod.Verifier(); v.detectLanguage('.'); await v.verifyFast('f',P,['src/index.ts']);
v=new mod.Verifier(); v.detectLanguage('.'); await v.verifyFast('f1',P,['src/index.ts']); await v.verifyFast('f2',P,['src/index.ts']);
